import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix='', env=os.environ):
    config = defaults.copy()
    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(toml_config)
        except FileNotFoundError:
            pass
    for key, value in env.items():
        if key.startswith(env_prefix):
            env_key = key[len(env_prefix):].replace('__', '.').lower()
            config_value = config.get(env_key)
            if config_value is not None:
                config[env_key] = _coerce_value(value, type(config_value))
    return config

def _coerce_value(value, target_type):
    if target_type is int:
        return int(value)
    elif target_type is float:
        return float(value)
    elif target_type is bool:
        return value.lower() in ('true', 'yes', '1')
    elif target_type is str:
        return value
    else:
        raise ConfigError(f'Unsupported type: {target_type}')

import pytest
from envcfg import load_config, ConfigError

def test_default_config():
    defaults = {'server': {'port': 8080}}
    assert load_config(defaults) == defaults

def test_toml_config():
    defaults = {'server': {'port': 8080}}
    toml_content = b'[server]\nport = 8081\n'
    with pytest.raises(FileNotFoundError):
        load_config(defaults, toml_path='config.toml')

def test_env_config():
    defaults = {'server': {'port': 8080}}
    env = {'APP__SERVER__PORT': '8082'}
    assert load_config(defaults, env_prefix='APP__', env=env) == {'server': {'port': 8082}}

def test_coerce_int():
    defaults = {'server': {'port': 8080}}
    env = {'APP__SERVER__PORT': '8081'}
    assert load_config(defaults, env_prefix='APP__', env=env) == {'server': {'port': 8081}}

def test_coerce_float():
    defaults = {'server': {'timeout': 0.5}}
    env = {'APP__SERVER__TIMEOUT': '0.6'}
    assert load_config(defaults, env_prefix='APP__', env=env) == {'server': {'timeout': 0.6}}

def test_coerce_bool():
    defaults = {'feature': {'enabled': False}}
    env = {'APP__FEATURE__ENABLED': 'true'}
    assert load_config(defaults, env_prefix='APP__', env=env) == {'feature': {'enabled': True}}

def test_coerce_str():
    defaults = {'message': 'hello'}
    env = {'APP__MESSAGE': 'world'}
    assert load_config(defaults, env_prefix='APP__', env=env) == {'message': 'world'}

def test_missing_default():
    defaults = {'server': {'port': 8080}}
    env = {'APP__SERVER__HOST': 'localhost'}
    with pytest.raises(ConfigError):
        load_config(defaults, env_prefix='APP__', env=env)

def test_invalid_coercion():
    defaults = {'server': {'port': 8080}}
    env = {'APP__SERVER__PORT': 'abc'}
    with pytest.raises(ConfigError):
        load_config(defaults, env_prefix='APP__', env=env)

